    memo = {}
    def get_score(current_cards, current_diff, is_grogg_turn):
        state = (current_cards, current_diff, is_grogg_turn)
        if state in memo:
            return memo[state]
        if not current_cards:
            return abs(current_diff)
        if is_grogg_turn:
            best_val = float('inf')
            for i in range(len(current_cards)):
                card = current_cards[i]
                remaining = current_cards[:i] + current_cards[i+1:]
                for sign in [1, -1]:
                    res = get_score(remaining, current_diff + sign * card, False)
                    best_val = min(best_val, res)
            memo[state] = best_val
            return best_val
