            best_val = float('-inf')
            for i in range(len(current_cards)):
                card = current_cards[i]
                remaining = current_cards[:i] + current_cards[i+1:]
                for sign in [1, -1]:
                    res = get_score(remaining, current_diff + sign * card, True)
                    best_val = max(best_val, res)
            memo[state] = best_val
            return best_val
    return get_score(current_cards, 0, True)

