def solve(n):
    cards = list(range(1, n + 1))

    # memoization table
    memo = {}

    def minimax(current_cards, current_diff, is_grogg_turn):
        # State can be represented by sorted tuple of remaining cards and current difference
        # Since difference D and -D are symmetric, we can use abs(current_diff)
        state = (tuple(sorted(current_cards)), abs(current_diff), is_grogg_turn)
        if state in memo:
            return memo[state]

        if not current_cards:
            return abs(current_diff)

        if is_grogg_turn:
            # Grogg wants to minimize the final |diff|
            best_val = float('inf')
            for i in range(len(current_cards)):
                card = current_cards[i]
                remaining = current_cards[:i] + current_cards[i+1:]
                # Grogg chooses pile 1 (+card) or pile 2 (-card)
                res1 = minimax(remaining, current_diff + card, False)
                res2 = minimax(remaining, current_diff - card, False)
                best_val = min(best_val, res1, res2)
            memo[state] = best_val
            return best_val
        else:
            # Winnie wants to maximize the final |diff|
            best_val = float('-inf')
            for i in range(len(current_cards)):
                card = current_cards[i]
                remaining = current_cards[:i] + current_cards[i+1:]
                # Winnie chooses pile 1 (+card) or pile 2 (-card)
                res1 = minimax(remaining, current_diff + card, True)
                res2 = minimax(remaining, current_diff - card, True)
                best_val = max(best_val, res1, res2)
            memo[state] = best_val
            return best_val

    return minimax(cards, 0, True)

